      buttonKey: const ValueKey('void-crumb-scroll-to-playing-track'),
      onTap: () => jumpToNowPlaying(playingPath),
      box: 44,
      glyph: '⊙',
      style: mono(palette.fgPrimary, typography.rowSize, height: 1),
    );

